/**
 * The dashboard's dictionaries, one per locale, which `i18n.ts` reads. Every
 * locale carries every key of `en`; a key missing from a locale falls back
 * to English at the lookup. Interpolation is `{name}`.
 * @module
 */

/** One locale's dictionary: nested string tables. */
export type Dictionary = { [key: string]: string | string[] | Dictionary };

